-- =============================================================================================
-- 12 lộ trình, 103 nút, 2,268 bản ghi tiến độ.

-- Flyway chạy file này qua chính pool của ứng dụng, nơi application.yml đặt
-- statement_timeout = 15s cho MỌI kết nối. Trần đó đúng cho một request người dùng và sai cho một
-- lần nạp dữ liệu hàng chục nghìn hàng. LOCAL: chỉ có hiệu lực trong giao dịch của migration này,
-- không rò sang bất kỳ kết nối nào khác của ứng dụng — dùng `SET` trần sẽ nới trần cho cả
-- connection sau khi nó được trả về pool, tức vô hiệu hoá một lớp bảo vệ có chủ đích ở một chỗ
-- hoàn toàn không liên quan.
SET LOCAL statement_timeout = 0;

-- FILE NÀY SINH TỰ ĐỘNG bởi scripts/seed/generate_seed.py — sửa tay sẽ bị ghi đè.
--
-- TOÀN BỘ NỘI DUNG LỘ TRÌNH DO NHÓM TỰ VIẾT, KHÔNG CHÉP TỪ roadmap.sh.
-- Giấy phép của kamranahmedse/developer-roadmap là "Other"/NOASSERTION, chỉ cho phép dùng cá nhân và
-- cấm publish nội dung dưới mọi hình thức — không phải giấy phép mã nguồn mở. Vi phạm ở đây nặng hơn
-- bình thường vì ba lý do cộng dồn: bộ seed chạy TRÊN PRODUCTION, nội dung nằm CÔNG KHAI TRONG REPO,
-- và đây là ĐỒ ÁN SẼ ĐƯỢC CHẤM. roadmap.sh chỉ được dùng để đối chiếu độ phủ chủ đề.
--
-- t_roadmaps và t_roadmap_nodes dùng SERIAL, nên setval ở cuối file gọi qua pg_get_serial_sequence.
--
-- CÂY NÚT: parent_node_id tự tham chiếu — nút gốc NULL, nút con trỏ tới id của nút cha CÙNG lộ
-- trình. Mọi hàng con đều nằm SAU hàng cha của nó trong câu INSERT, nên FK tự tham chiếu được thoả
-- mãn ngay trong một câu mà không cần hai lượt chèn. Không có ngẫu nhiên ở đây: chacon là nội dung
-- do nhóm thiết kế, ghi thẳng trong ROADMAPS ở generate_seed.py.
--
-- Tiến độ cố ý DANG DỞ: người học thật bỏ giữa chừng nhiều hơn hoàn thành, và một lộ trình ai cũng
-- xong 100% thì thanh tiến độ không còn gì để hiển thị. Tiến độ gắn trên MỌI cấp — khác seed cũ
-- (V58, chỉ nút lá), vì ở mô hình này nút gốc cũng là một kỹ năng học được, không chỉ là nhãn nhóm.

-- =============================================================================================

INSERT INTO socialapp.t_roadmaps (id, name, description, category, created_at, updated_at) VALUES
    (2001, 'Backend cho người mới', 'Từ một endpoint chạy được tới một dịch vụ chịu được tải thật.', 'BACKEND', now() - INTERVAL '500 days', now() - INTERVAL '500 days'),
    (2002, 'Frontend hiện đại', 'Từ HTML tĩnh tới giao diện chịu được dữ liệu thật và người dùng thật.', 'FRONTEND', now() - INTERVAL '492 days', now() - INTERVAL '492 days'),
    (2003, 'DevOps thực dụng', 'Đưa phần mềm ra môi trường thật và giữ nó sống.', 'DEVOPS', now() - INTERVAL '484 days', now() - INTERVAL '484 days'),
    (2004, 'Dữ liệu và học máy', 'Từ tệp CSV tới mô hình chạy trong sản xuất.', 'DATA_ML', now() - INTERVAL '476 days', now() - INTERVAL '476 days'),
    (2005, 'An toàn ứng dụng', 'Nghĩ như người tấn công để viết mã như người phòng thủ.', 'SECURITY', now() - INTERVAL '468 days', now() - INTERVAL '468 days'),
    (2006, 'Kiểm thử và chất lượng', 'Xây lưới an toàn để đội dám thay đổi mã.', 'QA', now() - INTERVAL '460 days', now() - INTERVAL '460 days'),
    (2007, 'Kỹ sư Mobile', 'Ứng dụng chạy tốt cả khi mạng chập chờn và pin sắp hết.', 'MOBILE', now() - INTERVAL '452 days', now() - INTERVAL '452 days'),
    (2008, 'Fullstack cân bằng', 'Đủ sâu ở hai đầu để không phải chờ người khác.', 'OTHER', now() - INTERVAL '444 days', now() - INTERVAL '444 days'),
    (2009, 'Nền tảng khoa học máy tính', 'Những thứ không đổi khi framework đổi.', 'OTHER', now() - INTERVAL '436 days', now() - INTERVAL '436 days'),
    (2010, 'Phát triển sự nghiệp', 'Kỹ năng quyết định bạn đi được bao xa, không phải bao nhanh.', 'CAREER', now() - INTERVAL '428 days', now() - INTERVAL '428 days'),
    (2011, 'Kiến trúc phần mềm', 'Ra quyết định lớn với ít thông tin, và ghi lại vì sao.', 'BACKEND', now() - INTERVAL '420 days', now() - INTERVAL '420 days'),
    (2012, 'Sản phẩm cho kỹ sư', 'Hiểu vì sao mình đang xây thứ này.', 'OTHER', now() - INTERVAL '412 days', now() - INTERVAL '412 days');

INSERT INTO socialapp.t_roadmap_nodes
    (id, roadmap_id, name, description, parent_node_id, order_index, created_at, updated_at) VALUES
    (1, 2001, 'Giao thức HTTP', 'Phương thức, mã trạng thái, header. 401 là chưa xác thực được ai gửi request, 403 là biết rồi nhưng không đủ quyền — hai lỗi hay bị đánh đồng.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (2, 2001, 'Một ngôn ngữ máy chủ', 'Chọn một và đi sâu: Java, Go, Python hay Node đều được — khảo sát nhà phát triển thường niên vẫn xếp cả bốn vào nhóm ngôn ngữ dùng nhiều nhất, không có lựa chọn sai.', NULL, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (3, 2001, 'Cơ sở dữ liệu quan hệ', 'Bảng, khoá, ràng buộc. Viết được truy vấn có JOIN mà không đoán — và biết vì sao khoá ngoại luôn cần một index trên cột bị tham chiếu.', NULL, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (4, 2001, 'Thiết kế API', 'Đặt tên tài nguyên, xử lý lỗi nhất quán, và phân trang kiểu cursor — trỏ tới bản ghi cuối thay vì đếm OFFSET, để không lặp hay bỏ sót dòng khi dữ liệu đang đổi.', 1, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (5, 2001, 'ORM và cái giá của nó', 'Hiểu N+1 sinh ra từ đâu, và vì sao JOIN FETCH gộp cha con vào một câu SQL cũng có giá riêng: tập kết quả phình to khi collection lớn, không phải liều thuốc chung.', 3, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (6, 2001, 'Giao dịch', 'Bốn tính chất ACID, mức cô lập từ Read Committed mặc định tới Serializable nghiêm ngặt nhất, và chuyện gọi nội bộ làm mất giao dịch.', 3, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (7, 2001, 'Đánh index', 'Thứ tự cột, tiền tố trái, partial index. Đọc được query plan — biết index tổ hợp chỉ thu hẹp vùng quét tới cột đầu tiên có điều kiện khoảng, cột sau đó chỉ lọc thêm.', 3, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (8, 2001, 'Caching', 'Chọn TTL, xử lý cache stampede bằng stale-while-revalidate — trả ngay bản cũ trong lúc âm thầm làm mới nền — và vấn đề khó nhất: vô hiệu hoá cache.', NULL, 7, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (9, 2001, 'Hàng đợi và việc nền', 'Tách việc chạy lâu khỏi request. Hàng đợi tiêu chuẩn chỉ cam kết giao ít nhất một lần — đôi khi giao trùng — nên phần xử lý luôn phải tự idempotent.', NULL, 8, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (10, 2001, 'Ghi log và đo đạc', 'Mã theo dõi xuyên suốt lan truyền qua header HTTP theo chuẩn W3C Trace Context, đo p99 thay vì trung bình.', NULL, 9, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (11, 2001, 'Kiểm thử', 'Test tích hợp trên đúng cơ sở dữ liệu mà production dùng — dựng bằng container thật cho mỗi lượt chạy rồi huỷ ngay, không dính trạng thái cũ.', NULL, 10, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (12, 2001, 'Triển khai', 'Biến môi trường tách khỏi mã nguồn theo nguyên tắc 12-factor để cùng một bản build chạy mọi môi trường, cộng migration và cách quay lui khi hỏng.', NULL, 11, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (13, 2002, 'HTML ngữ nghĩa', 'Dùng đúng thẻ để trình đọc màn hình tạo được landmark điều hướng theo vùng — đây cũng là bước đầu của khả năng truy cập.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (14, 2002, 'CSS bố cục', 'Flexbox và Grid. Đặt trước kích thước hoặc aspect-ratio để trình duyệt chừa đúng chỗ, hiểu vì sao thiếu nó gây layout shift làm người đọc mất chỗ.', NULL, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (15, 2002, 'JavaScript nền tảng', 'Bất đồng bộ, closure, module. Promise chạy trong microtask queue, luôn được xử lý hết trước khi event loop chuyển sang setTimeout dù cùng đặt độ trễ 0 — trước khi học framework.', NULL, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (16, 2002, 'TypeScript', 'Kiểu là tài liệu chạy được, bắt lỗi lúc biên dịch trước khi người dùng bắt — nhưng type bị xoá sạch khỏi JavaScript sinh ra, nên an toàn kiểu dừng lại ở biên dịch, không kéo tới runtime.', 15, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (17, 2002, 'Một framework', 'React, Vue hay Svelte. Hiểu vòng đời hai pha của nó: dựng cây so sánh trước, rồi mới ghi thật vào DOM đúng phần đã đổi.', 15, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (18, 2002, 'Quản lý trạng thái', 'Phân biệt trạng thái máy chủ — có thể đổi mà app không hay, vì một người khác vừa sửa — với trạng thái giao diện luôn đồng bộ với app.', 17, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (19, 2002, 'Gọi dữ liệu', 'Trạng thái tải, lỗi, rỗng — thư viện quản lý trạng thái máy chủ tách rõ ba trạng thái này thay vì gộp vào một cờ loading duy nhất. Đây là ba trạng thái hay bị quên nhất.', 17, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (20, 2002, 'Khả năng truy cập', 'Dùng được bằng bàn phím theo đúng thứ tự Tab có nghĩa (WCAG Focus Order), đọc được bằng trình đọc màn hình.', 13, 7, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (21, 2002, 'Hiệu năng web', 'Chia gói theo route để chỉ gửi đúng phần JavaScript của trang đang xem, tải ảnh đúng kích thước, đo bằng số thật.', NULL, 8, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (22, 2002, 'Kiểm thử giao diện', 'Test theo hành vi người dùng — tìm phần tử qua label, role, text như người dùng thật thấy — không theo chi tiết cài đặt bên trong, nên đổi cấu trúc component không làm test vỡ.', 17, 9, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (23, 2002, 'Dựng và đóng gói', 'Hiểu công cụ đang làm gì với mã của bạn: phục vụ qua module gốc để hot reload tức thì lúc code, rồi mới gộp và nén lại khi build production.', NULL, 10, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (24, 2003, 'Dòng lệnh Linux', 'Tệp, tiến trình, quyền chia ba nhóm chủ sở hữu/nhóm/người khác với ba bit đọc-ghi-thực thi mỗi nhóm. Đọc được log mà không cần giao diện.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (25, 2003, 'Quản lý phiên bản', 'Nhánh, gộp — fast-forward khi nhánh đích chưa đổi gì thêm, ba-way merge khi hai lịch sử đã phân nhánh — và cách viết lịch sử mà người sau đọc được.', NULL, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (26, 2003, 'Container', 'Image khác container: container chỉ thêm đúng một lớp ghi được lên trên các lớp chỉ đọc của image, nên nhiều container cùng image vẫn dùng chung phần lớn dữ liệu.', NULL, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (27, 2003, 'Tích hợp liên tục', 'Chạy test tự động. Build đỏ không phải vấn đề — theo đúng thực hành CI, không sửa ngay mới là vấn đề, vì nhánh chính hỏng chặn mọi người khác.', 25, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (28, 2003, 'Triển khai liên tục', 'Ra bản mới thường xuyên và nhỏ. Feature flag tách deploy khỏi release — code nằm sẵn ở trạng thái tắt, bật dần rồi tắt lại tức thì nếu hỏng, không cần rollback.', 27, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (29, 2003, 'Hạ tầng dưới dạng mã', 'Mô tả hạ tầng bằng tệp khai báo trạng thái đích mong muốn — không phải từng bước thao tác tay — và để công cụ tự tính kế hoạch đạt tới đó.', NULL, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (30, 2003, 'Điều phối container', 'Khi nào cần và khi nào chưa cần Kubernetes: vài container một máy thì chưa cần, nhưng hàng chục container trải nhiều máy đòi tự phục hồi và tự co giãn thì có.', 26, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (31, 2003, 'Giám sát', 'Chỉ số, log, vết. Công cụ giám sát kiểu pull chủ động ghé lấy số liệu theo chu kỳ, không chờ dịch vụ tự đẩy lên. Biết dịch vụ hỏng trước khi người dùng báo.', NULL, 7, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (32, 2003, 'Cảnh báo', 'Cảnh báo phải có một hành động rõ ràng người trực làm ngay được — sách SRE gọi cảnh báo không hành động được là nhiễu — nếu không nó sẽ bị tắt tiếng.', 31, 8, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (33, 2003, 'Sao lưu và khôi phục', 'Quy tắc 3-2-1: ba bản sao, hai loại lưu trữ khác nhau, một bản ở nơi khác — nhưng bản sao lưu chưa từng khôi phục thử thì chưa phải bản sao lưu.', NULL, 9, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (34, 2003, 'Chi phí', 'Đọc hoá đơn, tìm chỗ trả tiền cho thứ không ai dùng — phần lớn nằm ở tài nguyên đã ngừng dùng nhưng quên xoá, như ổ đĩa rời hay IP tĩnh không gắn máy nào.', NULL, 10, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (35, 2004, 'Python cho dữ liệu', 'Thao tác bảng dữ liệu bằng DataFrame hai chiều — lọc, gộp nhóm, join ngay trên đó — thành thạo trước khi nói tới mô hình.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (36, 2004, 'Thống kê nền tảng', 'Phân phối, tương quan, và vì sao tương quan không phải nhân quả — hai đại lượng có thể chỉ cùng chịu một biến ẩn thứ ba, không cái nào gây ra cái nào.', NULL, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (37, 2004, 'Làm sạch dữ liệu', 'Phần lớn thời gian nằm ở đây — nhiều khảo sát ngành liên tục cho thấy trên một phần ba thời gian người làm dữ liệu dành để dọn dữ liệu — không phải ở chỗ chọn thuật toán.', 35, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (38, 2004, 'Trực quan hoá', 'Biểu đồ để hiểu, không phải để trang trí báo cáo — phần trang trí không mang thông tin từng bị gọi thẳng là ''rác trực quan'' vì nó chỉ làm khó đọc thêm.', 35, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (39, 2004, 'Học có giám sát', 'Hồi quy và phân loại. Hiểu rò rỉ dữ liệu — xảy ra khi thông tin từ tập test lọt vào lúc huấn luyện, nên bước biến đổi dữ liệu luôn phải fit trên tập train rồi mới áp dụng sang tập test.', 36, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (40, 2004, 'Đánh giá mô hình', 'Chọn chỉ số hợp bài toán. Độ chính xác thường là chỉ số tệ — trên dữ liệu lệch lớp, một mô hình đoán bừa toàn lớp đông nhất vẫn đạt độ chính xác rất cao.', 39, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (41, 2004, 'Kỹ thuật đặc trưng', 'Đặc trưng tốt — biến đổi từ dữ liệu thô thành dạng mô hình học được — thắng mô hình phức tạp, gần như luôn luôn.', 37, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (42, 2004, 'Đường ống dữ liệu', 'Từ notebook sang quy trình chạy lại được — đúng cùng một đoạn mã chạy ở cả môi trường thử lẫn production, không viết lại hai lần.', NULL, 7, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (43, 2004, 'Đưa mô hình lên sản xuất', 'Phiên bản, theo dõi trôi dữ liệu — khi phân phối dữ liệu thật lệch dần khỏi lúc huấn luyện, mô hình mất độ chính xác dù code không đổi — và cách quay lui.', 42, 8, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (44, 2004, 'Đạo đức dữ liệu', 'Thiên lệch có sẵn trong dữ liệu huấn luyện thường bị mô hình khuếch đại thêm, chứ không chỉ phản ánh trung lập, rồi thành thiên lệch trong quyết định.', NULL, 9, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (45, 2005, 'Mô hình hoá mối đe doạ', 'Ai muốn gì, và họ vào bằng đường nào — mô hình STRIDE chia mối đe doạ thành sáu nhóm để rà từng phần hệ thống theo đúng khung đó.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (46, 2005, 'Xác thực', 'Mật khẩu băm bằng thuật toán cố tình chậm như bcrypt hay Argon2id kèm salt riêng từng mật khẩu, phiên hết hạn, và chống dò.', NULL, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (47, 2005, 'Phân quyền', 'Kiểm ở máy chủ, không tin id hay quyền mà client tự gửi lên. Ẩn nút trên giao diện không phải phân quyền — đây vẫn là nhóm lỗi phổ biến nhất theo OWASP nhiều năm liền.', 46, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (48, 2005, 'Mười rủi ro phổ biến', 'Danh sách OWASP xếp kiểm soát truy cập, lỗi mật mã và chèn mã ở nhóm đầu, có cả mục về toàn vẹn phần mềm và chuỗi cung ứng — đọc lại hằng năm vì nó đổi.', NULL, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (49, 2005, 'Chèn mã', 'SQL, lệnh hệ thống, mẫu. Câu lệnh tham số hoá khai báo trọn SQL trước, giá trị người dùng chỉ truyền vào sau như dữ liệu — cơ sở dữ liệu không lẫn nó với mã lệnh.', 48, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (50, 2005, 'Bí mật và khoá', 'Không nằm trong repo, đi qua công cụ quản lý bí mật tập trung có mã hoá và nhật ký ai lấy khoá nào lúc nào. Xoay vòng được khi lộ.', NULL, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (51, 2005, 'Phụ thuộc bên thứ ba', 'Chuỗi cung ứng là đường vào mà ít người canh — một cửa hậu từng bị cài thẳng vào một thư viện nén dùng rộng rãi trong Linux qua nhiều năm gây dựng danh tính giả để chiếm quyền maintainer, chỉ lộ ra vì một kỹ sư tình cờ để ý CPU dùng bất thường.', NULL, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (52, 2005, 'Ghi nhật ký an toàn', 'Ghi đủ để điều tra — đăng nhập thất bại, hành vi có quyền cao — nhưng không bao giờ ghi thẳng mật khẩu, khoá mã hay số thẻ thanh toán vào log.', NULL, 7, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (53, 2005, 'Xử lý sự cố', 'Biết trước sẽ gọi ai và làm gì — quy trình chuẩn chia bốn giai đoạn, và giai đoạn chuẩn bị luôn nằm trước khi có bất kỳ sự cố nào — trước khi cần đến.', NULL, 8, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (54, 2006, 'Kim tự tháp kiểm thử', 'Nhiều test nhỏ chạy nhanh ở tầng đáy, rất ít test chạy qua giao diện ở tầng đỉnh vì chúng chậm và dễ vỡ. Ngược lại thì chậm và giòn.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (55, 2006, 'Test đơn vị', 'Nhanh, độc lập, không phụ thuộc thứ tự chạy — chiếm phần lớn nhất trong tổng số test vì chi phí chạy và bảo trì rẻ nhất.', 54, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (56, 2006, 'Test tích hợp', 'Chạy trên đúng cơ sở dữ liệu mà production dùng — dựng bằng container thật cho mỗi lượt rồi huỷ ngay, không dính trạng thái để lại từ lượt trước.', 54, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (57, 2006, 'Test đầu cuối', 'Ít thôi vì đây là tầng chậm và dễ vỡ nhất trong ba tầng, và bám hành vi người dùng thay vì chi tiết bên trong.', 54, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (58, 2006, 'Dữ liệu kiểm thử', 'Dựng và dọn sạch sẽ — mỗi lượt test chạy trong một môi trường cô lập riêng, không dùng chung với lượt trước. Dữ liệu rớt lại làm test đỏ ngẫu nhiên.', 56, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (59, 2006, 'Test giòn', 'Nguyên nhân thường là chờ theo thời gian thay vì chờ theo điều kiện, hoặc phụ thuộc vào dịch vụ bên ngoài — cách xử lý phổ biến là tự động chạy lại rồi cách ly khỏi luồng CI quan trọng để không chặn cả đội.', 57, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (60, 2006, 'Độ phủ', 'Hữu ích như tín hiệu, tai hại như mục tiêu — đặt hẳn một phần trăm làm chỉ tiêu khiến người viết test đối phó cho đủ số, thay vì hỏi liệu mình có dám refactor tự tin không.', NULL, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (61, 2006, 'Kiểm thử hiệu năng', 'Đo dưới tải giống thật — tăng dần, đột biến, kéo dài — để phát hiện điểm nghẽn trước khi vi phạm SLO ngoài production, không phải trên máy cá nhân.', NULL, 7, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (62, 2006, 'Văn hoá chất lượng', 'Chất lượng là việc của cả đội ngay từ lúc thiết kế, không dồn hết trách nhiệm cho một vai kiểm thử ở cuối.', NULL, 8, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (63, 2007, 'Nền tảng và vòng đời', 'Màn hình bị huỷ và dựng lại bất cứ lúc nào — hệ điều hành gọi onSaveInstanceState trước khi dừng một activity, nhưng khi tiến trình bị hệ thống giết hẳn thì không một hàm vòng đời nào được gọi nữa, chỉ còn lại đúng phần dữ liệu đã lưu trước đó.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (64, 2007, 'Giao diện khai báo', 'Compose hoặc SwiftUI. Trạng thái quyết định giao diện — nâng state lên component cha (state hoisting) giữ đúng một nguồn sự thật, và mỗi lần state đổi hệ thống chỉ recompose lại đúng phần giao diện đang đọc state đó, không vẽ lại toàn màn hình.', 63, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (65, 2007, 'Lưu trữ cục bộ', 'Dữ liệu phải còn khi đóng ứng dụng.', NULL, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (66, 2007, 'Offline-first', 'Ghi trước, đồng bộ sau, và giải quyết xung đột — cách đơn giản nhất là để bản ghi mới nhất thắng, cách bền hơn là dùng CRDT để hợp nhất thay đổi từ nhiều thiết bị mà không cần một máy chủ trọng tài phân xử.', 65, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (67, 2007, 'Gọi mạng', 'Thử lại có giới hạn, và đừng thử lại thứ không idempotent — nên rắc thêm độ trễ ngẫu nhiên (jitter) vào khoảng chờ giữa các lần thử lại, nếu không toàn bộ client sẽ đồng loạt gọi lại cùng lúc và làm nghẽn chính máy chủ đang hồi phục.', NULL, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (68, 2007, 'Hiệu năng', 'Cuộn mượt quan trọng hơn mọi hiệu ứng.', NULL, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (69, 2007, 'Kích thước gói cài', 'Người dùng bỏ tải khi ứng dụng quá nặng — App Thinning trên iOS chỉ gửi đúng phần tài nguyên khớp với model máy đang cài thay vì một gói chung cho mọi thiết bị, có thể giảm dung lượng tải về tới 20-40%.', NULL, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (70, 2007, 'Phát hành', 'Kênh thử nghiệm, phát hành theo tỉ lệ, và cờ tính năng — một bản cập nhật thường lên trước cho một phần nhỏ người dùng rồi tăng dần theo từng mốc phần trăm, và có thể dừng ngay lập tức nếu phát hiện lỗi trước khi lỡ chạm tới toàn bộ người dùng.', NULL, 7, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (71, 2008, 'Nền tảng web', 'Trình duyệt làm gì với một request — từ tra DNS ra địa chỉ IP, bắt tay ba bước TCP, gửi request HTTP, tới lúc nhận response và bắt đầu dựng trang, mỗi bước đều có thể là nơi một request chậm đi mà không do lỗi ở tầng ứng dụng.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (72, 2008, 'Một ngôn ngữ hai đầu', 'Giảm chi phí chuyển ngữ cảnh trong ngày làm việc — dùng chung JavaScript/TypeScript ở cả client và server cho phép chia sẻ thẳng một bộ type hay một hàm validate giữa hai đầu, thay vì viết và giữ đồng bộ hai bản riêng biệt.', NULL, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (73, 2008, 'Ranh giới máy chủ và máy khách', 'Cái gì tính ở đâu, và vì sao — gọi đồng bộ giữa các phần giữ logic đơn giản nhưng kéo theo rủi ro lỗi dây chuyền khi một phía chậm, còn tách bất đồng bộ qua hàng đợi thì bền hơn nhưng cộng thêm độ trễ ở cả hai chiều.', 71, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (74, 2008, 'Thiết kế dữ liệu', 'Lược đồ quyết định phần lớn độ khó về sau.', NULL, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (75, 2008, 'Xác thực đầu cuối', 'Từ ô đăng nhập tới phân quyền ở tầng dịch vụ — OAuth 2.0 chỉ trả lời được ứng dụng được phép làm gì, còn biết chính xác ai đang đăng nhập cần thêm lớp OpenID Connect nằm trên nó, hai chuẩn tách biệt nhưng gần như luôn dùng cùng nhau trong thực tế.', 73, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (76, 2008, 'Trải nghiệm lập trình viên', 'Chạy được toàn bộ hệ thống bằng một lệnh — một lệnh compose dựng đủ web, API, database quen thuộc có thể rút thời gian dựng máy cho người mới từ vài giờ cài đặt thủ công xuống còn vài phút.', NULL, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (77, 2008, 'Triển khai một mình', 'Biết đủ hạ tầng để tự đưa sản phẩm ra — các nền tảng PaaS như Render hay Fly.io cho một người tự deploy thẳng từ git push mà không phải tự quản lý máy chủ, đánh đổi lại là ít quyền tinh chỉnh hạ tầng hơn so với tự dựng.', NULL, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (78, 2009, 'Cấu trúc dữ liệu', 'Mảng, bảng băm, cây, đồ thị. Biết chọn cái nào.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (79, 2009, 'Độ phức tạp', 'Ước lượng được trước khi đo — ký hiệu Big O mô tả tốc độ tăng của thời gian chạy theo kích thước dữ liệu đầu vào, bỏ qua hằng số, nên so sánh được hai thuật toán mà không cần chạy thử cả hai.', 78, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (80, 2009, 'Giải thuật cơ bản', 'Sắp xếp, tìm kiếm, duyệt đồ thị — thuật toán sắp xếp mặc định của Python và của Java từ bản 7 trở đi không phải quicksort thuần mà là Timsort, một thuật toán lai giữa merge sort và insertion sort được thiết kế riêng để tận dụng các đoạn đã có thứ tự sẵn trong dữ liệu thật.', 78, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (81, 2009, 'Hệ điều hành', 'Tiến trình, luồng, bộ nhớ, tệp — mỗi tiến trình có một vùng địa chỉ bộ nhớ riêng nên một tiến trình lỗi không thể ghi đè bộ nhớ của tiến trình khác, còn các luồng trong cùng một tiến trình dùng chung vùng địa chỉ đó nên giao tiếp nhanh hơn nhưng cũng dễ giẫm lên nhau hơn.', NULL, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (82, 2009, 'Mạng máy tính', 'Vì sao một request chậm mà CPU vẫn rảnh — trong lúc chờ phản hồi từ mạng, CPU không có gì để làm nên chuyển sang trạng thái rảnh; một request chờ 100ms lẽ ra trong quãng đó CPU có thể thực thi tới hàng trăm triệu lệnh nếu không phải chờ.', NULL, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (83, 2009, 'Hệ phân tán', 'Đánh đổi giữa nhất quán và sẵn sàng — định lý CAP nói rằng khi xảy ra chia cắt mạng, một hệ phân tán chỉ có thể giữ nhất quán dữ liệu hoặc tiếp tục phục vụ request, không thể giữ cả hai cùng lúc.', 82, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (84, 2010, 'Viết rõ ràng', 'Tài liệu và tin nhắn là công cụ làm việc chính của kỹ sư.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (85, 2010, 'Nhận và cho phản hồi', 'Tách con người khỏi đoạn mã — nguyên tắc cốt lõi của mô hình Radical Candor là phê bình hành vi hay công việc cụ thể, không phê bình con người, trong lúc vẫn thể hiện rõ mình quan tâm tới người nhận phản hồi.', NULL, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (86, 2010, 'Ước lượng', 'Nói được mức không chắc chắn thay vì một con số giả vờ chắc — ở giai đoạn mới hình thành ý tưởng, một ước lượng có thể sai lệch tới bốn lần theo cả hai hướng, và độ không chắc chắn đó chỉ thu hẹp đáng kể sau khi đã làm rõ được khoảng 20-30% khối lượng công việc.', NULL, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (87, 2010, 'Làm việc nhóm', 'Đồng bộ ít, tin nhau nhiều — một nghiên cứu kéo dài hai năm trên 180 đội của Google từng kết luận yếu tố phân biệt rõ nhất một đội hiệu quả không phải là ai giỏi nhất trong đội, mà là mức độ an toàn tâm lý: người trong đội dám nói sai, dám hỏi, mà không sợ bị đánh giá.', 85, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (88, 2010, 'Phỏng vấn', 'Cả hai phía đều đang đánh giá lẫn nhau — ứng viên chủ động hỏi ngược lại về đội và cách làm việc không chỉ để lấy thông tin mà bản thân việc đặt câu hỏi tốt cũng là một tín hiệu nhà tuyển dụng thường để ý.', NULL, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (89, 2010, 'Dẫn dắt kỹ thuật', 'Ra quyết định và chịu trách nhiệm về nó — ghi lại quyết định theo mẫu do Michael Nygard đề xuất năm 2011 (bối cảnh, quyết định, hệ quả) giúp người dẫn dắt để lại một dấu vết lý do rõ ràng thay vì chỉ để lại kết quả cuối cùng.', 87, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (90, 2010, 'Học liên tục', 'Chọn thứ đáng học, bỏ qua thứ đang ồn ào — một kỹ sư dạng chữ T có một mảng chuyên sâu cộng với hiểu biết rộng ở nhiều mảng liên quan, nên khi một công nghệ chính mình theo đuổi hết thời vẫn còn nền để xoay sang hướng khác.', NULL, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (91, 2011, 'Ghép lỏng và gắn kết', 'Hai chỉ số cũ mà vẫn đúng — coupling và cohesion do Larry Constantine đưa ra từ cuối thập niên 1960 và công bố rộng năm 1974, tới nay vẫn là nền cho hàng trăm nghiên cứu và nhiều thước đo chất lượng mã nguồn khác.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (92, 2011, 'Kiến trúc phân tầng', 'Đơn giản, đủ dùng cho phần lớn hệ thống — tầng trình bày gọi tầng nghiệp vụ, tầng nghiệp vụ gọi tầng truy cập dữ liệu, mỗi tầng chỉ biết tầng ngay dưới mình nên đổi database về lý thuyết không đụng tới logic nghiệp vụ phía trên.', 91, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (93, 2011, 'Thiết kế theo miền', 'Ngôn ngữ chung giữa kỹ sư và người dùng — Eric Evans gọi đó là ngôn ngữ phổ dụng (ubiquitous language), dùng chung một từ vựng giữa người làm nghiệp vụ và người viết code trong đúng một ranh giới ngữ cảnh (bounded context) để tránh cùng một từ mang hai nghĩa khác nhau ở hai nơi.', NULL, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (94, 2011, 'Khi nào tách dịch vụ', 'Câu trả lời thường là chưa — Martin Fowler quan sát thấy các đội thành công thường bắt đầu từ một monolith rồi mới tách dần khi nó thực sự trở thành vấn đề, còn các đội tách microservices ngay từ đầu dự án phần nhiều gặp khó khăn.', 92, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (95, 2011, 'Giao tiếp giữa dịch vụ', 'Đồng bộ hay bất đồng bộ, và cái giá của mỗi lựa chọn — gọi đồng bộ dễ theo dõi nhưng một dịch vụ ở giữa chuỗi gọi bị chậm sẽ kéo chậm toàn bộ chuỗi, còn đưa qua hàng đợi bất đồng bộ chịu lỗi tốt hơn nhưng cộng thêm độ trễ qua hai lượt hàng đợi ở cả hai chiều.', 94, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (96, 2011, 'Ghi lại quyết định', 'Một trang cho mỗi quyết định lớn, kèm phương án đã loại — mẫu ghi quyết định kiến trúc (ADR) Michael Nygard đề xuất năm 2011 chỉ gồm vài mục: bối cảnh, quyết định, hệ quả, đủ ngắn để thực sự được viết trong lúc làm việc.', NULL, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (97, 2011, 'Tiến hoá hệ thống', 'Đổi dần, không viết lại — kiến trúc tiến hoá dùng các ''hàm thích nghi'' (fitness function) là những phép kiểm, chỉ số hay cơ chế giám sát chạy liên tục để xác nhận một đặc tính kiến trúc quan trọng vẫn được giữ đúng sau mỗi lần thay đổi.', NULL, 6, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (98, 2012, 'Phát hiện vấn đề', 'Người dùng nói triệu chứng, không nói nguyên nhân — kỹ thuật 5 Whys của Toyota hỏi liên tiếp ''vì sao'' cho tới khi chạm được nguyên nhân gốc mang tính hệ thống, thay vì dừng lại ở lớp triệu chứng đầu tiên rồi vá tạm.', NULL, 0, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (99, 2012, 'Nghiên cứu người dùng', 'Quan sát nhiều hơn hỏi — nguyên tắc đầu tiên Nielsen Norman Group nhấn mạnh là đừng thiết kế theo lời người dùng tự nói mình muốn gì, vì lời kể lại về hành vi tương lai vốn không đáng tin bằng việc quan sát trực tiếp họ thao tác.', 98, 1, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (100, 2012, 'Chỉ số', 'Chọn chỉ số mà đội có thể tác động được — một North Star Metric tốt vừa phản ánh đúng giá trị cốt lõi sản phẩm mang lại cho người dùng, vừa phải là thứ đội ngũ thực sự có thể tác động qua các cải tiến của mình, không phải một con số chỉ nhìn lại quá khứ.', NULL, 2, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (101, 2012, 'Phạm vi', 'Cắt phạm vi là kỹ năng, không phải thất bại.', NULL, 3, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (102, 2012, 'Thử nghiệm', 'Bản nhỏ nhất trả lời được câu hỏi — vòng lặp build-measure-learn của Eric Ries dùng một sản phẩm khả dụng tối thiểu (MVP) để thu về lượng kiểm chứng thực tế lớn nhất với công sức bỏ ra ít nhất, rồi rút ngắn vòng lặp đó càng nhanh càng tốt.', 101, 4, now() - INTERVAL '400 days', now() - INTERVAL '400 days'),
    (103, 2012, 'Tăng trưởng', 'Giữ chân trước, mở rộng sau — mô hình ''thùng rò'' ví người dùng mới đổ vào như nước đổ vào một thùng thủng đáy: đổ thêm bao nhiêu ở trên mà đáy vẫn rò thì tăng trưởng ròng vẫn phẳng, nên vá tỉ lệ giữ chân luôn phải đi trước khi đổ thêm ngân sách thu hút người dùng mới.', 100, 5, now() - INTERVAL '400 days', now() - INTERVAL '400 days');

